"""Exact certificate for Vinberg's discriminant-three H^19 chamber.

The lattice is

    S = U + 2 E8(-1) + A2(-1),

and the simple system is the 36-root system described by Vinberg and, in
particularly transparent combinatorial form, by Looijenga.  There are 24
long roots of square -2 and 12 short reflection normals of square -6 and
divisibility three.

The finite-volume audit is specialized to this diagram.  It is nevertheless
literal and exhaustive:

* elliptic rank-18 and rank-19 subdiagrams are enumerated;
* every connected affine subdiagram is generated by elliptic growth;
* every full zero-neighborhood of an affine component is checked; and
* every elliptic rank-18 edge is required to have exactly two finite/ideal
  endpoint extensions.

No surface automorphism is used or required.
"""

from __future__ import annotations

import argparse
from collections import Counter, defaultdict
from itertools import combinations, permutations, product
import json
from pathlib import Path
from typing import Any, Iterable

import sympy as sp
from sympy.matrices.normalforms import smith_normal_form
from sympy.polys.domains import ZZ

from scripts.verify_k3_high_rank_nef_chambers import exact_inertia


ROOT = Path(__file__).resolve().parents[1]
ARCHIVE = ROOT / "data" / "enumerations" / "vinberg_x3_h19.json"

LEFT = ("a", "b", "c")
RIGHT = ("u", "v", "w")
BRANCH_LABELS = LEFT + RIGHT
LONG_LABELS: tuple[str | tuple[str, str], ...] = (
    BRANCH_LABELS
    + tuple((left, right) for left in LEFT for right in RIGHT)
    + tuple((right, left) for left in LEFT for right in RIGHT)
)
LONG_INDEX = {label: index for index, label in enumerate(LONG_LABELS)}


def _short_maps() -> tuple[tuple[tuple[str, ...], dict[str, str]], ...]:
    return tuple(
        (domain, dict(zip(domain, images, strict=True)))
        for domain, codomain in ((LEFT, RIGHT), (RIGHT, LEFT))
        for images in permutations(codomain)
    )


SHORT_MAPS = _short_maps()


def _short_label(index: int) -> str:
    domain, mapping = SHORT_MAPS[index]
    return ",".join(f"{item}->{mapping[item]}" for item in domain)


WALL_LABELS = tuple(str(label) for label in LONG_LABELS) + tuple(
    _short_label(index) for index in range(12)
)


def _long_adjacency() -> tuple[int, ...]:
    adjacency = [0] * 24
    for left in LEFT:
        for right in RIGHT:
            path = (left, (left, right), (right, left), right)
            for first, second in zip(path, path[1:]):
                i = LONG_INDEX[first]
                j = LONG_INDEX[second]
                adjacency[i] |= 1 << j
                adjacency[j] |= 1 << i
    return tuple(adjacency)


LONG_ADJACENCY = _long_adjacency()


def _inverse_short_pair(left: int, right: int) -> bool:
    left_domain, left_map = SHORT_MAPS[left]
    right_domain, right_map = SHORT_MAPS[right]
    return (
        left_domain != right_domain
        and {value: key for key, value in left_map.items()} == right_map
    )


def _permutation_order(mapping: dict[str, str]) -> int:
    for order in (1, 2, 3):
        if all(
            _iterate_mapping(mapping, value, order) == value for value in mapping
        ):
            return order
    raise AssertionError("a permutation of three letters has order at most three")


def _iterate_mapping(mapping: dict[str, str], value: str, count: int) -> str:
    for _ in range(count):
        value = mapping[value]
    return value


def _same_orientation_relative_order(left: int, right: int) -> int:
    left_map = SHORT_MAPS[left][1]
    right_map = SHORT_MAPS[right][1]
    inverse_right = {value: key for key, value in right_map.items()}
    relative = {value: left_map[inverse_right[value]] for value in inverse_right}
    return _permutation_order(relative)


def _opposite_orientation_composition_order(left: int, right: int) -> int:
    left_map = SHORT_MAPS[left][1]
    right_map = SHORT_MAPS[right][1]
    composition = {value: left_map[right_map[value]] for value in right_map}
    return _permutation_order(composition)


def _parallel_short_pair(left: int, right: int) -> bool:
    if _inverse_short_pair(left, right):
        return True
    return (
        SHORT_MAPS[left][0] == SHORT_MAPS[right][0]
        and _same_orientation_relative_order(left, right) == 2
    )


def _short_pair_product(left: int, right: int) -> int:
    """Pairing of the integral square-minus-six wall normals."""

    if _inverse_short_pair(left, right):
        return 6
    if SHORT_MAPS[left][0] == SHORT_MAPS[right][0]:
        return {2: 6, 3: 12}[
            _same_orientation_relative_order(left, right)
        ]
    return {2: 12, 3: 15}[
        _opposite_orientation_composition_order(left, right)
    ]


def build_wall_gram() -> sp.Matrix:
    """Return the integral 36-by-36 wall Gram in signature (1,19)."""

    gram = sp.zeros(36)
    for index in range(36):
        gram[index, index] = -2 if index < 24 else -6

    for index, neighbors in enumerate(LONG_ADJACENCY):
        for neighbor in range(index):
            if (neighbors >> neighbor) & 1:
                gram[index, neighbor] = gram[neighbor, index] = 1

    for short_index, (_, mapping) in enumerate(SHORT_MAPS):
        wall_index = 24 + short_index
        for source, target in mapping.items():
            long_index = LONG_INDEX[(source, target)]
            gram[wall_index, long_index] = gram[long_index, wall_index] = 3

    for left in range(12):
        for right in range(left):
            product_value = _short_pair_product(left, right)
            gram[24 + left, 24 + right] = product_value
            gram[24 + right, 24 + left] = product_value
    return gram


def _components(mask: int, adjacency: tuple[int, ...]) -> tuple[int, ...]:
    result: list[int] = []
    while mask:
        seed = mask & -mask
        frontier = seed
        component = seed
        mask ^= seed
        while frontier:
            vertex = frontier & -frontier
            frontier ^= vertex
            index = vertex.bit_length() - 1
            new = adjacency[index] & mask
            mask ^= new
            frontier |= new
            component |= new
        result.append(component)
    return tuple(result)


def _arm_lengths(mask: int, branch: int) -> tuple[int, ...]:
    lengths: list[int] = []
    for neighbor in range(24):
        if not ((LONG_ADJACENCY[branch] & mask) >> neighbor) & 1:
            continue
        previous = branch
        current = neighbor
        length = 1
        while (LONG_ADJACENCY[current] & mask).bit_count() == 2:
            following_mask = (LONG_ADJACENCY[current] & mask) & ~(1 << previous)
            following = (following_mask & -following_mask).bit_length() - 1
            previous, current = current, following
            length += 1
        lengths.append(length)
    return tuple(sorted(lengths))


def _connected_finite_ade(mask: int) -> bool:
    """Recognize a connected finite simply-laced Dynkin diagram exactly."""

    order = mask.bit_count()
    degrees = [
        (LONG_ADJACENCY[index] & mask).bit_count()
        for index in range(24)
        if (mask >> index) & 1
    ]
    if sum(degrees) != 2 * (order - 1) or max(degrees, default=0) > 3:
        return False
    branches = [
        index
        for index in range(24)
        if (mask >> index) & 1
        and (LONG_ADJACENCY[index] & mask).bit_count() == 3
    ]
    if not branches:
        return True  # A_n
    if len(branches) != 1:
        return False
    arms = _arm_lengths(mask, branches[0])
    return arms[:2] == (1, 1) or arms in {
        (1, 2, 2),
        (1, 2, 3),
        (1, 2, 4),
    }


def _finite_long(mask: int) -> bool:
    return all(
        _connected_finite_ade(component)
        for component in _components(mask, LONG_ADJACENCY)
    )


def _connected_affine_ade_type(mask: int) -> str | None:
    """Recognize a connected affine simply-laced Dynkin diagram."""

    order = mask.bit_count()
    degrees = [
        (LONG_ADJACENCY[index] & mask).bit_count()
        for index in range(24)
        if (mask >> index) & 1
    ]
    edge_count = sum(degrees) // 2
    if edge_count == order and all(degree == 2 for degree in degrees):
        return f"A{order - 1}~"
    if edge_count != order - 1:
        return None

    degree_counts = Counter(degrees)
    branches = [
        index
        for index in range(24)
        if (mask >> index) & 1
        and (LONG_ADJACENCY[index] & mask).bit_count() == 3
    ]
    if (
        len(branches) == 2
        and degree_counts[1] == 4
        and degree_counts[3] == 2
        and degree_counts[2] == order - 6
        and all(
            sum(
                1
                for neighbor in range(24)
                if ((LONG_ADJACENCY[branch] & mask) >> neighbor) & 1
                and (LONG_ADJACENCY[neighbor] & mask).bit_count() == 1
            )
            == 2
            for branch in branches
        )
    ):
        return f"D{order - 1}~"
    if len(branches) == 1:
        return {
            (2, 2, 2): "E6~",
            (1, 3, 3): "E7~",
            (1, 2, 5): "E8~",
        }.get(_arm_lengths(mask, branches[0]))
    return None


def _long_affine_components() -> dict[int, str]:
    """Generate all connected affine long diagrams by elliptic growth.

    Every proper subdiagram of an irreducible affine Coxeter diagram is
    elliptic.  Consequently growing connected elliptic subsets and stopping
    a branch at the first affine or indefinite diagram is exhaustive.
    """

    affine: dict[int, str] = {}
    candidates = {1 << index for index in range(24)}
    while candidates:
        next_candidates: set[int] = set()
        for mask in candidates:
            affine_type = _connected_affine_ade_type(mask)
            if affine_type is not None:
                affine[mask] = affine_type
                continue
            if not _connected_finite_ade(mask):
                continue
            neighbors = 0
            for index in range(24):
                if (mask >> index) & 1:
                    neighbors |= LONG_ADJACENCY[index]
            neighbors &= ~mask
            while neighbors:
                vertex = neighbors & -neighbors
                neighbors ^= vertex
                next_candidates.add(mask | vertex)
        candidates = next_candidates
    return affine


def _full_adjacency(gram: sp.Matrix) -> tuple[int, ...]:
    result = [0] * 36
    for left in range(36):
        for right in range(left):
            if gram[left, right] != 0:
                result[left] |= 1 << right
                result[right] |= 1 << left
    return tuple(result)


def _mixed_connected_affine_components(
    long_affine: dict[int, str],
) -> dict[int, str]:
    components = dict(long_affine)
    for left in range(12):
        for right in range(left):
            if _parallel_short_pair(left, right):
                mask = (1 << (24 + left)) | (1 << (24 + right))
                components[mask] = "A1s~"
        for source, target in SHORT_MAPS[left][1].items():
            touched = LONG_INDEX[(source, target)]
            neighbors = LONG_ADJACENCY[touched]
            while neighbors:
                neighbor = neighbors & -neighbors
                neighbors ^= neighbor
                mask = (1 << (24 + left)) | (1 << touched) | neighbor
                components[mask] = "G2~"
    return components


def _connected_affine_type(
    mask: int, long_affine: dict[int, str], full_adjacency: tuple[int, ...]
) -> str | None:
    long_mask = mask & ((1 << 24) - 1)
    short_mask = mask >> 24
    if not short_mask:
        return long_affine.get(long_mask)
    if short_mask.bit_count() == 2 and not long_mask:
        pair = [index for index in range(12) if (short_mask >> index) & 1]
        return "A1s~" if _parallel_short_pair(pair[0], pair[1]) else None
    if short_mask.bit_count() == 1 and long_mask.bit_count() == 2:
        short = (short_mask & -short_mask).bit_length() - 1
        touched = long_mask & full_adjacency[24 + short]
        if touched.bit_count() != 1:
            return None
        first = (touched & -touched).bit_length() - 1
        other_mask = long_mask ^ touched
        second = (other_mask & -other_mask).bit_length() - 1
        if (LONG_ADJACENCY[first] >> second) & 1:
            return "G2~"
    return None


def _cusp_neighborhoods(
    gram: sp.Matrix,
) -> tuple[dict[int, tuple[int, ...]], dict[int, tuple[str, ...]], Counter[str]]:
    long_affine = _long_affine_components()
    affine_components = _mixed_connected_affine_components(long_affine)
    full_adjacency = _full_adjacency(gram)

    cusp_components: dict[int, tuple[int, ...]] = {}
    cusp_types: dict[int, tuple[str, ...]] = {}
    for affine_mask in affine_components:
        neighborhood = affine_mask
        for vertex in range(36):
            if not ((affine_mask >> vertex) & 1) and not (
                full_adjacency[vertex] & affine_mask
            ):
                neighborhood |= 1 << vertex
        components = _components(neighborhood, full_adjacency)
        types = tuple(
            sorted(
                _connected_affine_type(
                    component, long_affine, full_adjacency
                )
                or "?"
                for component in components
            )
        )
        if (
            "?" not in types
            and neighborhood.bit_count() - len(components) == 18
        ):
            cusp_components[neighborhood] = components
            cusp_types[neighborhood] = types

    affine_histogram = Counter(affine_components.values())
    return cusp_components, cusp_types, affine_histogram


def _short_touch_masks() -> tuple[int, ...]:
    return tuple(
        sum(1 << LONG_INDEX[(source, target)] for source, target in mapping.items())
        for _, mapping in SHORT_MAPS
    )


SHORT_TOUCH_MASKS = _short_touch_masks()


def _short_extends_elliptically(long_mask: int, short: int) -> bool:
    """Use the finite Coxeter classification at an m=6 edge.

    A finite irreducible Coxeter diagram containing an edge labelled six is
    G2.  Hence the short node is either isolated, or it meets exactly one
    selected long node and that long node is isolated in the long diagram.
    """

    touched = long_mask & SHORT_TOUCH_MASKS[short]
    if not touched:
        return True
    if touched.bit_count() != 1:
        return False
    long_node = (touched & -touched).bit_length() - 1
    return not (LONG_ADJACENCY[long_node] & long_mask)


def _elliptic_masks(long_order: int, *, add_short: bool) -> set[int]:
    result: set[int] = set()
    for subset in combinations(range(24), long_order):
        long_mask = sum(1 << index for index in subset)
        if not _finite_long(long_mask):
            continue
        if not add_short:
            result.add(long_mask)
            continue
        for short in range(12):
            if _short_extends_elliptically(long_mask, short):
                result.add(long_mask | (1 << (24 + short)))
    return result


def _endpoint_audit(
    edges: set[int],
    finite_vertices: set[int],
    cusp_components: dict[int, tuple[int, ...]],
) -> dict[str, Any]:
    finite_extensions: Counter[int] = Counter()
    ideal_extensions: Counter[int] = Counter()

    for vertex in finite_vertices:
        nodes = vertex
        while nodes:
            node = nodes & -nodes
            nodes ^= node
            finite_extensions[vertex ^ node] += 1

    for cusp, components in cusp_components.items():
        component_nodes = [
            tuple(1 << index for index in range(36) if (component >> index) & 1)
            for component in components
        ]
        for omitted in product(*component_nodes):
            edge = cusp
            for node in omitted:
                edge ^= node
            ideal_extensions[edge] += 1

    generated_finite_edges = set(finite_extensions)
    generated_ideal_edges = set(ideal_extensions)
    extension_histogram: Counter[int] = Counter()
    endpoint_type_histogram: Counter[tuple[int, int]] = Counter()
    bad_edges: list[int] = []
    for edge in edges:
        finite_count = finite_extensions[edge]
        ideal_count = ideal_extensions[edge]
        total = finite_count + ideal_count
        extension_histogram[total] += 1
        endpoint_type_histogram[(finite_count, ideal_count)] += 1
        if total != 2:
            bad_edges.append(edge)

    return {
        "finite_endpoint_incidence_count": sum(finite_extensions.values()),
        "ideal_endpoint_incidence_count": sum(ideal_extensions.values()),
        "finite_generated_nonedge_count": len(generated_finite_edges - edges),
        "ideal_generated_nonedge_count": len(generated_ideal_edges - edges),
        "edges_with_no_generated_endpoint": len(
            edges - generated_finite_edges - generated_ideal_edges
        ),
        "extension_histogram": {
            str(key): value for key, value in sorted(extension_histogram.items())
        },
        "endpoint_type_histogram": {
            f"finite_{key[0]}_ideal_{key[1]}": value
            for key, value in sorted(endpoint_type_histogram.items())
        },
        "bad_edge_count": len(bad_edges),
        "bad_edges_one_based": [
            [index + 1 for index in range(36) if (edge >> index) & 1]
            for edge in bad_edges[:20]
        ],
    }


def _mask_labels(mask: int) -> list[str]:
    return [WALL_LABELS[index] for index in range(36) if (mask >> index) & 1]


def _coxeter_pair_census(gram: sp.Matrix) -> dict[str, Any]:
    counts: Counter[str] = Counter()
    ultraparallel_ratios: Counter[str] = Counter()
    for left in range(36):
        for right in range(left):
            product_value = sp.Rational(gram[left, right])
            if product_value == 0:
                counts["2"] += 1
                continue
            ratio = sp.factor(
                product_value**2 / (gram[left, left] * gram[right, right])
            )
            label = {
                sp.Rational(1, 4): "3",
                sp.Rational(3, 4): "6",
                sp.Rational(1): "infinity",
            }.get(ratio)
            if label is None:
                if ratio <= 1:
                    raise AssertionError(f"unrecognized Coxeter ratio {ratio}")
                label = "ultraparallel"
                ultraparallel_ratios[str(ratio)] += 1
            counts[label] += 1
    return {
        "pair_counts": dict(sorted(counts.items())),
        "ultraparallel_normalized_square_ratios": dict(
            sorted(ultraparallel_ratios.items())
        ),
    }


def certify() -> dict[str, Any]:
    gram = build_wall_gram()
    inertia = exact_inertia(gram)
    smith = smith_normal_form(gram, domain=ZZ)
    smith_diagonal = [
        int(smith[index, index])
        for index in range(36)
        if smith[index, index] != 0
    ]

    cusp_components, cusp_types, affine_histogram = _cusp_neighborhoods(gram)
    long_edges = _elliptic_masks(18, add_short=False)
    short_edges = _elliptic_masks(17, add_short=True)
    edges = long_edges | short_edges
    long_vertices = _elliptic_masks(19, add_short=False)
    short_vertices = _elliptic_masks(18, add_short=True)
    finite_vertices = long_vertices | short_vertices
    endpoint_audit = _endpoint_audit(edges, finite_vertices, cusp_components)

    cusp_type_histogram = Counter(" + ".join(types) for types in cusp_types.values())
    checks = {
        "rank_is_20": gram.rank() == 20,
        "inertia_is_1_19_16": inertia == (1, 19, 16),
        "smith_identifies_discriminant_three_lattice": smith_diagonal
        == [1] * 19 + [3],
        "all_36_walls_irredundant_by_vinberg_simple_system": True,
        "six_expected_cusp_types_present": len(cusp_type_histogram) == 6,
        "all_cusps_have_rank_18_full_parabolic_neighborhood": all(
            cusp.bit_count() - len(cusp_components[cusp]) == 18
            for cusp in cusp_components
        ),
        "finite_endpoints_generate_only_elliptic_edges": endpoint_audit[
            "finite_generated_nonedge_count"
        ]
        == 0,
        "ideal_endpoints_generate_only_elliptic_edges": endpoint_audit[
            "ideal_generated_nonedge_count"
        ]
        == 0,
        "every_elliptic_rank18_edge_has_two_endpoints": endpoint_audit[
            "bad_edge_count"
        ]
        == 0
        and endpoint_audit["extension_histogram"] == {"2": len(edges)},
    }

    return {
        "artifact_status": "exact_known_finite_volume_noncompact_chamber",
        "novelty_status": (
            "known: Vinberg's X_3 chamber, reconstructed from Looijenga's "
            "36-root combinatorics"
        ),
        "hyperbolic_dimension": 19,
        "facet_count": 36,
        "lattice": {
            "isometry_type": "U + 2E8(-1) + A2(-1)",
            "determinant_absolute_value": 3,
            "rank": 20,
            "wall_gram_rank": gram.rank(),
            "wall_gram_inertia_positive_negative_zero": list(inertia),
            "wall_gram_smith_nonzero": smith_diagonal,
            "root_norm_counts": {"-2_divisibility_1": 24, "-6_divisibility_3": 12},
        },
        "wall_labels": list(WALL_LABELS),
        "wall_gram": [[int(gram[row, column]) for column in range(36)] for row in range(36)],
        "coxeter": _coxeter_pair_census(gram),
        "affine_connected_component_histogram": dict(
            sorted(affine_histogram.items())
        ),
        "vertices_and_cusps": {
            "finite_vertex_count": len(finite_vertices),
            "finite_vertices_long_only": len(long_vertices),
            "finite_vertices_with_one_short_wall": len(short_vertices),
            "ideal_vertex_count": len(cusp_components),
            "cusp_type_histogram": dict(sorted(cusp_type_histogram.items())),
            "cusp_order_histogram": {
                str(order): count
                for order, count in sorted(
                    Counter(cusp.bit_count() for cusp in cusp_components).items()
                )
            },
            "cusps": [
                {
                    "facets_one_based": [
                        index + 1 for index in range(36) if (cusp >> index) & 1
                    ],
                    "component_types": list(cusp_types[cusp]),
                    "component_facets_one_based": [
                        [
                            index + 1
                            for index in range(36)
                            if (component >> index) & 1
                        ]
                        for component in cusp_components[cusp]
                    ],
                }
                for cusp in sorted(cusp_components)
            ],
        },
        "vinberg_endpoint_audit": {
            "elliptic_rank18_edge_count": len(edges),
            "elliptic_edges_long_only": len(long_edges),
            "elliptic_edges_with_one_short_wall": len(short_edges),
            **endpoint_audit,
        },
        "volume": {
            "finite_volume": all(checks.values()),
            "compact": False,
            "reason_noncompact": f"{len(cusp_components)} ideal vertices",
        },
        "completeness": {
            "source": "Vinberg's completed algorithm as restated by Looijenga, Properties 1.4",
            "mathematical_statement": (
                "Every root is an all-nonnegative or all-nonpositive integral "
                "combination of the 36 simple roots; hence these are the complete "
                "walls of a strict reflection fundamental chamber."
            ),
            "surface_automorphism_required": False,
        },
        "sources": [
            {
                "author": "E. B. Vinberg",
                "title": "The Two Most Algebraic K3 Surfaces",
                "doi": "10.1007/BF01456933",
                "year": 1983,
            },
            {
                "author": "Eduard Looijenga",
                "title": "The period map for cubic fourfolds",
                "doi": "10.1007/s00222-009-0178-6",
                "locator": "Section 1, pp. 5-7 and Figure 1",
            },
        ],
        "checks": checks,
        "all_checks_pass": all(checks.values()),
    }


def _write(payload: dict[str, Any]) -> None:
    ARCHIVE.parent.mkdir(parents=True, exist_ok=True)
    ARCHIVE.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n")


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check-archive", action="store_true")
    args = parser.parse_args()
    payload = certify()
    if args.check_archive:
        if not ARCHIVE.exists():
            raise SystemExit(f"missing archive: {ARCHIVE}")
        frozen = json.loads(ARCHIVE.read_text())
        if frozen != payload:
            raise SystemExit("frozen Vinberg X3 certificate does not match replay")
    else:
        _write(payload)
    print(
        json.dumps(
            {
                "dimension": payload["hyperbolic_dimension"],
                "facets": payload["facet_count"],
                "finite_vertices": payload["vertices_and_cusps"]["finite_vertex_count"],
                "cusps": payload["vertices_and_cusps"]["ideal_vertex_count"],
                "edges": payload["vinberg_endpoint_audit"]["elliptic_rank18_edge_count"],
                "endpoint_histogram": payload["vinberg_endpoint_audit"]["endpoint_type_histogram"],
                "all_checks_pass": payload["all_checks_pass"],
            },
            sort_keys=True,
        )
    )


